async(page)=>{
 const checks=[],base='E:/Dr.RouteFit/prototype/records/2026-10-24-warehouse-platform/';
 const assert=(ok,m)=>{if(!ok)throw Error(m)};
 const state=()=>page.evaluate(()=>JSON.parse(sessionStorage.getItem('routefit-r1-prototype-v1')));
 const role=async r=>{await page.locator(`[data-role=${r}]`).first().click();if(r==='dispatch')await page.locator('[data-dispatch-tab=orders]').click()};
 const nav=async v=>page.locator(`[data-nav=${v}]`).first().click();
 const tab=async v=>page.locator(`[data-section-tab=${v}]`).click();
 const open=async a=>page.locator(`[data-action=${a}]`).first().click();
 const fill=async p=>{for(const [k,v]of Object.entries(p)){const el=page.locator(`#action-form [name=${k}]`);if(k==='vehicle'){await page.locator(`#action-form [name=vehicle][value="${v}"]`).check();continue;}if(typeof v==='boolean')await el.setChecked(v);else if(await el.evaluate(x=>x.tagName)==='SELECT')await el.selectOption(String(v));else await el.fill(String(v))}};
 const submit=async()=>{await page.locator('#action-form [type=submit]').click();await page.locator('#dialog').waitFor({state:'hidden',timeout:4000})};
 const act=async(a,p={})=>{await open(a);await fill(p);await submit()};
 const bad=async(a,p,expected)=>{await open(a);await fill(p);await page.locator('#action-form [type=submit]').click();await page.waitForFunction(t=>document.querySelector('#form-error')?.textContent.includes(t),expected);assert((await page.locator('#form-error').innerText()).includes(expected),'Missing guard '+a);await page.locator('[data-close]').first().click();if(await page.locator('#dialog').isVisible())await page.locator('[data-close]').first().click()};
 await page.goto('http://127.0.0.1:4173/prototype/');await page.reload();await page.setViewportSize({width:1440,height:1000});await role('dispatch');await open('qa');await act('reset');await role('ops');await page.screenshot({path:base+'operations.png',fullPage:true});
 await nav('goods');await act('goodsNew',{code:'DEMO-BOX-NEW',name:'仓配演示包装箱',unit:'件',weight:10,length:40,width:30,height:20,active:true});let db=await state();const sku=db.goods.at(-1).id;assert(db.goods.at(-1).active,'new SKU inactive');await act('goodsEdit',{weight:11});assert((await state()).goods.at(-1).weight===11,'SKU edit failed');
 await nav('inventory');await act('stockReceive',{goodsId:sku,qty:10,evidence:'DEMO-INBOUND',checked:true});await tab('moves');assert((await page.locator('main').innerText()).includes('DEMO-INBOUND'),'receipt ledger absent');await tab('warehouses');await act('warehouseNew',{name:'演示备用仓',location:'演示地址 B'});assert((await state()).warehouses.length===2,'warehouse create failed');checks.push('商品规格维护、入库、库存流水、仓库资料');
 await nav('vehicles');await page.locator('[data-resource=V02]').click();await act('vehicleEdit',{capacity:1250});assert((await state()).vehicleProfiles.find(v=>v.id==='V02').capacity===1250,'vehicle edit failed');
 await nav('drivers');await act('driverNew',{name:'新司机 · 演示',identityRef:'DEMO-ID-NEW',licenseRef:'DEMO-LIC-NEW'});await act('driverReview',{evidence:'DEMO-IDENTITY-REVIEW',confirmed:true});assert((await state()).driverProfiles.at(-1).status==='verified','identity review failed');checks.push('车辆容量维护、司机身份登记与准入审核');
 await role('driver');await page.locator('[data-driver-tab=profile]').click();await tab('bank');await act('bankSave',{bank:'演示银行',holder:'Sokha DEMO',last4:'1234',confirmed:true});await role('finance');await nav('drivers');await page.locator('[data-resource=D01]').click();await tab('bank');await act('bankReview',{evidence:'DEMO-ACCOUNT-REVIEW',confirmed:true});checks.push('司机银行卡后四位提交、财务归属核验');
 await role('dispatch');await act('create',{goodsId:sku,serviceType:'flash',customer:'演示仓配客户',destination:'演示收货地点',qty:2,amount:20,flashFee:5,commissionPercent:20});db=await state();const oid=db.orders[0].id;assert(db.orders[0].amountMinor===2500,'flash fee not included');await bad('promise',{basis:'DEMO-RESOURCE',address:true,measured:true,confirmed:true},'闪送');await act('promise',{basis:'DEMO-RESOURCE',address:true,measured:true,confirmed:true,exclusive:true,flashConfirmed:true});assert((await state()).stockReservations[oid].status==='held','stock not reserved');await act('offer',{vehicle:'V01'});await role('driver');await act('accept');await role('warehouse');await act('prepare',{dimension:true,pattern:true,packaging:true,evidence:'DEMO-LOAD'});await role('driver');await act('pickup',{evidence:'DEMO-PICKUP'});await act('depart');db=await state();assert(db.stockReservations[oid].status==='issued','stock not issued');assert(db.stockMoves.filter(m=>m.goodsId===sku&&m.bucket==='available').reduce((n,m)=>n+m.qty,0)===8,'stock amount wrong');
 await act('report',{proof:'DEMO-CASH'});await act('deliver',{receiver:'演示收货人',evidence:'DEMO-POD'});await role('finance');await act('verify',{evidence:'DEMO-CASH-CHECK'});await role('driver');await act('remit',{evidence:'DEMO-REMIT'});await role('finance');await act('reconcile',{evidence:'DEMO-RECONCILE'});await nav('pricing');await tab('orders');await page.locator(`[data-resource="${oid}"]`).click();await act('earningPost',{evidence:'DEMO-EARNING-CHECK'});db=await state();assert(db.earnings[0].driverMinor===2000&&db.earnings[0].platformMinor===500,'split totals wrong');await tab('earnings');await page.screenshot({path:base+'commission-ledger.png',fullPage:true});checks.push('商品关联独享闪送 → 库存预留 → 交接出库 → 签收收款交款 → 20% 示例分成入账');
 await role('driver');await page.locator('[data-driver-tab=profile]').click();await tab('withdraw');await bad('withdrawRequest',{amount:21,confirmed:true},'可用收入');await act('withdrawRequest',{amount:12,confirmed:true});await tab('bank');await bad('bankSave',{last4:'9999',confirmed:true},'在途提现');await tab('withdraw');await page.setViewportSize({width:390,height:844});assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),'wallet mobile overflow');await page.screenshot({path:base+'driver-wallet.png',fullPage:true});await page.setViewportSize({width:1440,height:1000});await role('finance');await nav('withdrawals');await page.locator('[data-resource=WD-001]').click();await act('withdrawApprove',{evidence:'DEMO-WITHDRAW-REVIEW'});await act('withdrawPaid',{evidence:'DEMO-MANUAL-PAYMENT'});await page.screenshot({path:base+'withdraw-paid.png',fullPage:true});assert((await state()).withdrawals[0].status==='paid','withdraw not paid');checks.push('提现超额阻断、冻结收入、在途禁止换卡、财务审核与人工付款');
 await role('driver');await page.locator('[data-driver-tab=profile]').click();await tab('withdraw');await act('withdrawRequest',{amount:8,confirmed:true});await role('finance');await nav('withdrawals');await page.locator('[data-resource=WD-002]').click();await act('withdrawReject',{evidence:'演示资料待补充'});await role('driver');await page.locator('[data-driver-tab=profile]').click();await tab('income');assert((await page.locator('.wallet-stats').innerText()).includes('8.00'),'reject balance not restored');await page.locator('#driver-actor').selectOption('D03');assert((await page.locator('.wallet-stats').innerText()).includes('0.00'),'driver income leaked');checks.push('驳回释放余额、不同司机收入隔离');
 await page.setViewportSize({width:1280,height:900});await role('ops');for(const v of ['goods','inventory','vehicles','drivers','pricing','withdrawals','partners']){await nav(v);assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),v+' horizontal overflow');if(v==='partners')assert(!await page.locator('[data-action=partnerApprove]').isVisible(),'partner details stacked with list')};await nav('inventory');await page.screenshot({path:base+'inventory.png',fullPage:true});await page.reload();assert((await state()).withdrawals[0].status==='paid','refresh lost state');checks.push('全部新增后台菜单与 1280px 布局、刷新保留');
 return {browser:'PASS',checks};
}
